_current_language = 'ru'

def get_system_default_language() -> str:
    try:
        loc, _ = locale.getdefaultlocale()
        if loc and loc.split('_')[0].lower() == 'ru':
            return 'ru'
    except Exception:
        pass
    return 'ru'

def set_language(lang_code: str) -> None:
    global _current_language
    if lang_code in LANGUAGES:
        _current_language = lang_code
    elif lang_code and lang_code.startswith('ru'):
        _current_language = 'ru'
    else:
        _current_language = 'en'

def get_current_language() -> str:
    return _current_language

def t(key: str, **kwargs) -> str:
    lang_dict = TRANSLATIONS.get(_current_language, TRANSLATIONS.get('ru', {}))
    val = lang_dict.get(key, TRANSLATIONS.get('en', {}).get(key, key))
    if kwargs:
        try:
            return val.format(**kwargs)
        except Exception:
            return val
    return val
